import pytest
import unittest.mock
from bionetgen.simulator.csimulator import CSimWrapper
from bionetgen.core.exc import BNGSimulatorError


def test_set_parameters_error():
    with unittest.mock.patch("bionetgen.simulator.csimulator.ctypes.CDLL"):
        wrapper = CSimWrapper("dummy_lib_path", num_params=3, num_spec_init=2)
        with pytest.raises(BNGSimulatorError) as excinfo:
            wrapper.set_parameters([1.0, 2.0])
        # The exception message generated by BNGSimulatorError based on actual file contents
        assert "Expected 3 parameters, but got 2" in str(excinfo.value)


import ctypes
import numpy as np


def test_simulate():
    with unittest.mock.patch("bionetgen.simulator.csimulator.ctypes.CDLL") as mock_cdll:
        mock_lib = unittest.mock.MagicMock()
        mock_cdll.return_value = mock_lib

        wrapper = CSimWrapper("dummy_lib_path", num_params=1, num_spec_init=1)
        wrapper.set_species_init([1.0])
        wrapper.set_parameters([1.0])

        # Prepare strings for obs_names and spcs_names matching the C formatting (split by '/')
        obs_names_str = b"obs1/\x00"
        obs_names_buf = ctypes.create_string_buffer(obs_names_str)
        spcs_names_str = b"spcs1/\x00"
        spcs_names_buf = ctypes.create_string_buffer(spcs_names_str)

        # Prepare arrays for obs and species
        ntpts = 101  # default n_steps=100 -> 101 timepoints
        obs_array = np.zeros(ntpts * 1, dtype=np.float64)
        spcs_array = np.zeros(ntpts * 1, dtype=np.float64)

        # Result struct mock setup
        res = wrapper.return_struct()
        res.obs_name_len = len(obs_names_str)
        res.obs_names = ctypes.cast(obs_names_buf, ctypes.POINTER(ctypes.c_char))
        res.spcs_name_len = len(spcs_names_str)
        res.spcs_names = ctypes.cast(spcs_names_buf, ctypes.POINTER(ctypes.c_char))
        res.n_observables = 1
        res.observables = ctypes.cast(
            obs_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
            ctypes.POINTER(ctypes.c_double),
        )
        res.n_species = 1
        res.species = ctypes.cast(
            spcs_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
            ctypes.POINTER(ctypes.c_double),
        )

        # Patch from_address to return our mocked result struct
        with unittest.mock.patch.object(
            wrapper.return_struct, "from_address", return_value=res
        ) as mock_from_address:
            timepoints, obs_all, spcs_all = wrapper.simulate(0, 100, 100)

            assert len(timepoints) == 101
            assert "obs1" in obs_all.dtype.names
            assert "spcs1" in spcs_all.dtype.names
